# bash completion for gh-safe-repo
# Generated by `gh-safe-repo --completion bash`; do not edit.
#   load it:  source <(gh-safe-repo --completion bash)   (e.g. in ~/.bashrc)
#   or copy this file to ~/.local/share/bash-completion/completions/gh-safe-repo

_gh_safe_repo_values() {
    # $1: what to complete (file, dir, w:<words>, or empty); $2: the current word
    case "$1" in
        file|dir)
            compopt -o filenames 2>/dev/null
            local IFS=$'\n'
            if [[ "$1" == dir ]]; then
                COMPREPLY=( $(compgen -d -- "$2") )
            else
                COMPREPLY=( $(compgen -f -- "$2") )
            fi
            ;;
        w:*) COMPREPLY=( $(compgen -W "${1#w:}" -- "$2") ) ;;
        *) COMPREPLY=() ;;
    esac
}

_gh_safe_repo() {
    local cur prev cmd='' cmd_at=0 opts='' valopts='' rest='' i w n npos=0 kind
    local -a pos=()
    COMPREPLY=()
    cur="${COMP_WORDS[COMP_CWORD]}"
    n=$((COMP_CWORD - 1))
    # `--opt=value`: COMP_WORDBREAKS splits it into `--opt`, `=`, `value`.
    if [[ "$cur" == "=" ]]; then cur=""; prev="${COMP_WORDS[n]}"
    else
        prev="${COMP_WORDS[n]-}"
        [[ "$prev" == "=" ]] && prev="${COMP_WORDS[n-1]-}"
    fi

    # The command is the first word that is neither an option nor an option's value.
    for (( i=1; i < COMP_CWORD; i++ )); do
        w="${COMP_WORDS[i]}"
        case "$w" in
            --config)
                [[ "${COMP_WORDS[i+1]-}" == "=" ]] && (( i++ ))
                (( i++ )) ;;
            -*|=) ;;
            *) cmd="$w"; cmd_at=$i; break ;;
        esac
    done

    case "$cmd" in
        "")
            opts='-h --help -v --version --debug --config --no-config'
            valopts=' --config '
            case "$prev" in
                --config)
                    _gh_safe_repo_values 'file' "$cur"; return 0 ;;
            esac
            ;;
        new)
            opts='-h --help --public --dry-run --yes -y --debug --config --no-config --json'
            valopts=' --config '
            pos=( '' )
            case "$prev" in
                --config)
                    _gh_safe_repo_values 'file' "$cur"; return 0 ;;
            esac
            ;;
        push)
            opts='-h --help --public --dry-run --yes -y --debug --config --no-config --json'
            valopts=' --config '
            pos=( 'dir' '' )
            case "$prev" in
                --config)
                    _gh_safe_repo_values 'file' "$cur"; return 0 ;;
            esac
            ;;
        copy)
            opts='-h --help --public --dry-run --yes -y --debug --config --no-config --json'
            valopts=' --config '
            pos=( '' '' )
            case "$prev" in
                --config)
                    _gh_safe_repo_values 'file' "$cur"; return 0 ;;
            esac
            ;;
        audit)
            opts='-h --help --all --debug --config --no-config --json'
            valopts=' --config '
            pos=( '' )
            case "$prev" in
                --config)
                    _gh_safe_repo_values 'file' "$cur"; return 0 ;;
            esac
            ;;
        fix)
            opts='-h --help --dry-run --yes -y --all --migrate-branch-protection --debug --config --no-config --json'
            valopts=' --config '
            pos=( '' )
            case "$prev" in
                --config)
                    _gh_safe_repo_values 'file' "$cur"; return 0 ;;
            esac
            ;;
        scan)
            opts='-h --help --debug --config --no-config --json'
            valopts=' --config '
            pos=( 'dir' )
            case "$prev" in
                --config)
                    _gh_safe_repo_values 'file' "$cur"; return 0 ;;
            esac
            ;;
        *) return 0 ;;
    esac

    if [[ "$cur" == -* ]]; then
        COMPREPLY=( $(compgen -W "$opts" -- "$cur") )
        return 0
    fi
    if [[ -z "$cmd" ]]; then
        COMPREPLY=( $(compgen -W 'new push copy audit fix scan' -- "$cur") )
        return 0
    fi

    # Which positional is being typed: count the plain words after the command.
    for (( i=cmd_at+1; i < COMP_CWORD; i++ )); do
        w="${COMP_WORDS[i]}"
        if [[ "$valopts" == *" $w "* ]]; then
            [[ "${COMP_WORDS[i+1]-}" == "=" ]] && (( i++ ))
            (( i++ ))
        elif [[ "$w" != -* && "$w" != "=" ]]; then
            (( npos++ ))
        fi
    done
    if (( npos < ${#pos[@]} )); then
        kind="${pos[npos]}"
    else
        kind="$rest"
    fi
    if [[ -n "$kind" ]]; then
        _gh_safe_repo_values "$kind" "$cur"
    else
        COMPREPLY=( $(compgen -W "$opts" -- "$cur") )
    fi
    return 0
}

complete -F _gh_safe_repo gh-safe-repo
